<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Ujian</title><style>*{box-sizing:border-box}body{margin:0;background:#071827;color:#e2f8f4;font:14px/1.6 Arial,sans-serif}.wrap{max-width:680px;margin:auto;padding:50px 20px}.brand{color:#67e8d0;font-size:12px;font-weight:bold;letter-spacing:2px}.card{margin-top:24px;border:1px solid #234051;border-radius:22px;background:#102536;padding:30px;box-shadow:0 25px 80px #0005}.status{display:inline-block;border-radius:99px;padding:7px 12px;background:{{ $valid ? '#5ee9bd' : '#fb7185' }};color:#07251e;font-size:11px;font-weight:bold}.card h1{margin:20px 0 5px;font-size:27px}.muted{color:#9ab1bc}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:25px}.item{border:1px solid #294455;border-radius:12px;padding:13px;background:#0b1d2b}.item small{display:block;color:#83a3ae;font-size:10px;text-transform:uppercase}.item strong{display:block;margin-top:4px;color:white}.footer{margin-top:22px;color:#75909a;font-size:11px;text-align:center}@media(max-width:540px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="brand">SIAKAD · DIGITAL TRUST</div><section class="card"><span class="status">{{ $valid ? '✓ JADWAL VALID' : '! TIDAK AKTIF' }}</span><h1>{{ $exam->classGroup->course->code }} · {{ $exam->classGroup->course->name }}</h1><p class="muted">Hasil pemeriksaan jadwal ujian pada registri resmi {{ config('siakad.institution') }}.</p><div class="grid"><div class="item"><small>Jenis</small><strong>{{ strtoupper($exam->exam_type) }}</strong></div><div class="item"><small>Periode</small><strong>{{ $exam->academicTerm->code }}</strong></div><div class="item"><small>Tanggal</small><strong>{{ $exam->exam_date->locale('id')->translatedFormat('d F Y') }}</strong></div><div class="item"><small>Waktu</small><strong>{{ substr($exam->starts_at,0,5) }}–{{ substr($exam->ends_at,0,5) }}</strong></div></div></section><div class="footer">Kode verifikasi {{ $exam->verification_code }} · Data peserta tidak ditampilkan untuk menjaga privasi.</div></main></body></html>
